func BenchmarkEncodeDecodeSchematic(b *testing.B) {
	seed := v11.Schematic{
		Key:      uuid.MustParse("a1b2c3d4-e5f6-7890-abcd-ef1234567801"),
		Name:     "test_2",
		Snapshot: true,
		Nodes: []v11.Node{
			{
				Key:      "test_5",
				Position: spatial.XY{X: 7.5, Y: 8.5},
				ZIndex:   10,
			},
		},
		Edges: []v11.Edge{
			{
				Key:    "test_11",
				Source: v11.Handle{Node: "test_13", Param: "test_14"},
				Target: v11.Handle{Node: "test_16", Param: "test_17"},
			},
		},
		Configs: map[string]v11.ElementConfig{"test_18": {Variant: v11.CapElementConfig{StaticSymbolConfig: fullyPopulatedStaticSymbolConfig}}},
	}
	w := orc.NewWriter(0)
	r := orc.NewReader(nil)
	for b.Loop() {
		w.Reset()
		if err := seed.EncodeOrc(w); err != nil {
			b.Fatal(err)
		}
		var decoded v11.Schematic
		r.ResetBytes(w.Bytes())
		if err := decoded.DecodeOrc(r); err != nil {
			b.Fatal(err)
		}
	}
}

